from typing import List

def max_servings(Q: List[int], A: List[int], B: List[int]) -> int:
    def canmake(K: int) -> bool:
        for x in range(K + 1):
            if all(A[i] * x + B[i] * (K - x) <= Q[i] for i in range(len(Q))):
                return True
        return False

    L, R = 0, 10**6
    while R - L > 1:
        C = (R + L) // 2
        if canmake(C):
            L = C
        else:
            R = C

    return L
